1  import React, {useCallback, useEffect, useMemo, useRef, useState} from 'react';
     2  import {View} from 'react-native';
     3  import type {OnyxEntry} from 'react-native-onyx';
     4  import {useOnyx} from 'react-native-onyx';
     5  import useLocalize from '@hooks/useLocalize';
     6  import useNetwork from '@hooks/useNetwork';
     7  import useResponsiveLayout from '@hooks/useResponsiveLayout';
     8  import useTheme from '@hooks/useTheme';
     9  import useThemeStyles from '@hooks/useThemeStyles';
    10  import * as CurrencyUtils from '@libs/CurrencyUtils';
    11  import Navigation from '@libs/Navigation/Navigation';
    12  import * as PolicyUtils from '@libs/PolicyUtils';
    13  import * as ReportActionsUtils from '@libs/ReportActionsUtils';
    14  import * as ReportUtils from '@libs/ReportUtils';
    15  import * as TransactionUtils from '@libs/TransactionUtils';
    16  import variables from '@styles/variables';
    17  import * as IOU from '@userActions/IOU';
    18  import * as TransactionActions from '@userActions/Transaction';
    19  import CONST from '@src/CONST';
    20  import useDelegateUserDetails from '@src/hooks/useDelegateUserDetails';
    21  import ONYXKEYS from '@src/ONYXKEYS';
    22  import type {Route} from '@src/ROUTES';
    23  import ROUTES from '@src/ROUTES';
    24  import type * as OnyxTypes from '@src/types/onyx';
    25  import type {PaymentMethodType} from '@src/types/onyx/OriginalMessage';
    26  import type IconAsset from '@src/types/utils/IconAsset';
    27  import isLoadingOnyxValue from '@src/types/utils/isLoadingOnyxValue';
    28  import Button from './Button';
    29  import ConfirmModal from './ConfirmModal';
    30  import DelegateNoAccessModal from './DelegateNoAccessModal';
    31  import HeaderWithBackButton from './HeaderWithBackButton';
    32  import Icon from './Icon';
    33  import * as Expensicons from './Icon/Expensicons';
    34  import MoneyReportHeaderStatusBar from './MoneyReportHeaderStatusBar';
    35  import type {MoneyRequestHeaderStatusBarProps} from './MoneyRequestHeaderStatusBar';
    36  import MoneyRequestHeaderStatusBar from './MoneyRequestHeaderStatusBar';
    37  import type {ActionHandledType} from './ProcessMoneyReportHoldMenu';
    38  import ProcessMoneyReportHoldMenu from './ProcessMoneyReportHoldMenu';
    39  import ProcessMoneyRequestHoldMenu from './ProcessMoneyRequestHoldMenu';
    40  import ExportWithDropdownMenu from './ReportActionItem/ExportWithDropdownMenu';
    41  import SettlementButton from './SettlementButton';
    42
    43  type MoneyReportHeaderProps = {
    44      /** The report currently being looked at */
    45      report: OnyxEntry<OnyxTypes.Report>;
    46
    47      /** The policy tied to the expense report */
    48      policy: OnyxEntry<OnyxTypes.Policy>;
    49
    50      /** Array of report actions for the report */
    51      reportActions: OnyxTypes.ReportAction[];
    52
    53      /** The reportID of the transaction thread report associated with this current report, if any */
    54      // eslint-disable-next-line react/no-unused-prop-types
    55      transactionThreadReportID?: string | null;
    56
    57      /** Method to trigger when pressing close button of the header */
    58      onBackButtonPress: () => void;
    59  };
    60
    61  function MoneyReportHeader({policy, report: moneyRequestReport, transactionThreadReportID, reportActions, onBackButtonPress}: MoneyReportHeaderProps) {
    62      const {shouldUseNarrowLayout, isSmallScreenWidth} = useResponsiveLayout();
    63      const [chatReport] = useOnyx(`${ONYXKEYS.COLLECTION.REPORT}${moneyRequestReport?.chatReportID ?? '-1'}`);
    64      const [nextStep] = useOnyx(`${ONYXKEYS.COLLECTION.NEXT_STEP}${moneyRequestReport?.reportID ?? '-1'}`);
    65      const [transactionThreadReport] = useOnyx(`${ONYXKEYS.COLLECTION.REPORT}${transactionThreadReportID}`);
    66      const [session] = useOnyx(ONYXKEYS.SESSION);
    67      const requestParentReportAction = useMemo(() => {
    68          if (!reportActions || !transactionThreadReport?.parentReportActionID) {
    69              return null;
    70          }
    71          return reportActions.find((action): action is OnyxTypes.ReportAction<typeof CONST.REPORT.ACTIONS.TYPE.IOU> => action.reportActionID === transactionThreadReport.parentReportActionID);
    72      }, [reportActions, transactionThreadReport?.parentReportActionID]);
    73      const [transactions] = useOnyx(ONYXKEYS.COLLECTION.TRANSACTION);
    74      const [dismissedHoldUseExplanation, dismissedHoldUseExplanationResult] = useOnyx(ONYXKEYS.NVP_DISMISSED_HOLD_USE_EXPLANATION, {initialValue: true});
    75      const isLoadingHoldUseExplained = isLoadingOnyxValue(dismissedHoldUseExplanationResult);
    76      const transaction =
    77          transactions?.[
    78              `${ONYXKEYS.COLLECTION.TRANSACTION}${
    79                  ReportActionsUtils.isMoneyRequestAction(requestParentReportAction) ? ReportActionsUtils.getOriginalMessage(requestParentReportAction)?.IOUTransactionID ?? -1 : -1
    80              }`
    81          ] ?? undefined;
    82
    83      const styles = useThemeStyles();
    84      const theme = useTheme();
    85      const [isDeleteRequestModalVisible, setIsDeleteRequestModalVisible] = useState(false);
    86      const [shouldShowHoldMenu, setShouldShowHoldMenu] = useState(false);
    87      const {translate} = useLocalize();
    88      const {isOffline} = useNetwork();
    89      const {reimbursableSpend} = ReportUtils.getMoneyRequestSpendBreakdown(moneyRequestReport);
    90      const isOnHold = TransactionUtils.isOnHold(transaction);
    91      const isDeletedParentAction = !!requestParentReportAction && ReportActionsUtils.isDeletedAction(requestParentReportAction);
    92
    93      // Only the requestor can delete the request, admins can only edit it.
    94      const isActionOwner =
    95          typeof requestParentReportAction?.actorAccountID === 'number' && typeof session?.accountID === 'number' && requestParentReportAction.actorAccountID === session?.accountID;
    96      const canDeleteRequest = isActionOwner && ReportUtils.canDeleteTransaction(moneyRequestReport) && !isDeletedParentAction;
    97      const [isHoldMenuVisible, setIsHoldMenuVisible] = useState(false);
    98      const [paymentType, setPaymentType] = useState<PaymentMethodType>();
    99      const [requestType, setRequestType] = useState<ActionHandledType>();
   100      // eslint-disable-next-line react-compiler/react-compiler, react-hooks/exhaustive-deps
   101      const allTransactions = useMemo(() => TransactionUtils.getAllReportTransactions(moneyRequestReport?.reportID), [moneyRequestReport?.reportID, transactions]);
   102      const canAllowSettlement = ReportUtils.hasUpdatedTotal(moneyRequestReport, policy);
   103      const policyType = policy?.type;
   104      const isDraft = ReportUtils.isOpenExpenseReport(moneyRequestReport);
   105      const connectedIntegration = PolicyUtils.getConnectedIntegration(policy);
   106      const navigateBackToAfterDelete = useRef<Route>();
   107      const hasScanningReceipt = ReportUtils.getTransactionsWithReceipts(moneyRequestReport?.reportID).some((t) => TransactionUtils.isReceiptBeingScanned(t));
   108      const hasOnlyPendingTransactions = allTransactions.length > 0 && allTransactions.every((t) => TransactionUtils.isExpensifyCardTransaction(t) && TransactionUtils.isPending(t));
   109      const transactionIDs = allTransactions.map((t) => t.transactionID);
   110      const hasAllPendingRTERViolations = TransactionUtils.allHavePendingRTERViolation([transaction?.transactionID ?? '-1']);
   111      const hasOnlyHeldExpenses = ReportUtils.hasOnlyHeldExpenses(moneyRequestReport?.reportID ?? '');
   112      const isPayAtEndExpense = TransactionUtils.isPayAtEndExpense(transaction);
   113      const isArchivedReport = ReportUtils.isArchivedRoomWithID(moneyRequestReport?.reportID);
   114      const [archiveReason] = useOnyx(`${ONYXKEYS.COLLECTION.REPORT_ACTIONS}${moneyRequestReport?.reportID ?? '-1'}`, {selector: ReportUtils.getArchiveReason});
   115
   116      const shouldShowPayButton = useMemo(
   117          () => IOU.canIOUBePaid(moneyRequestReport, chatReport, policy, transaction ? [transaction] : undefined),
   118          [moneyRequestReport, chatReport, policy, transaction],
   119      );
   120
   121      const shouldShowApproveButton = useMemo(() => IOU.canApproveIOU(moneyRequestReport, policy), [moneyRequestReport, policy]);
   122
   123      const shouldDisableApproveButton = shouldShowApproveButton && !ReportUtils.isAllowedToApproveExpenseReport(moneyRequestReport);
   124
   125      const shouldShowSubmitButton = !!moneyRequestReport && isDraft && reimbursableSpend !== 0 && !hasAllPendingRTERViolations;
   126
   127      const isAdmin = policy?.role === CONST.POLICY.ROLE.ADMIN;
   128      const shouldShowExportIntegrationButton = !shouldShowPayButton && !shouldShowSubmitButton && connectedIntegration && isAdmin && ReportUtils.canBeExported(moneyRequestReport);
   129
   130      const shouldShowSettlementButton = (shouldShowPayButton || shouldShowApproveButton) && !hasAllPendingRTERViolations && !shouldShowExportIntegrationButton;
   131
   132      const shouldDisableSubmitButton = shouldShowSubmitButton && !ReportUtils.isAllowedToSubmitDraftExpenseReport(moneyRequestReport);
   133      const isFromPaidPolicy = policyType === CONST.POLICY.TYPE.TEAM || policyType === CONST.POLICY.TYPE.CORPORATE;
   134      const shouldShowStatusBar = hasAllPendingRTERViolations || hasOnlyHeldExpenses || hasScanningReceipt || isPayAtEndExpense || hasOnlyPendingTransactions;
   135      const shouldShowNextStep = !ReportUtils.isClosedExpenseReportWithNoExpenses(moneyRequestReport) && isFromPaidPolicy && !!nextStep?.message?.length && !shouldShowStatusBar;
   136      const shouldShowAnyButton =
   137          shouldShowSettlementButton || shouldShowApproveButton || shouldShowSubmitButton || shouldShowNextStep || hasAllPendingRTERViolations || shouldShowExportIntegrationButton;
   138      const bankAccountRoute = ReportUtils.getBankAccountRoute(chatReport);
   139      const formattedAmount = CurrencyUtils.convertToDisplayString(reimbursableSpend, moneyRequestReport?.currency);
   140      const [nonHeldAmount, fullAmount] = ReportUtils.getNonHeldAndFullAmount(moneyRequestReport, policy);
   141      const isAnyTransactionOnHold = ReportUtils.hasHeldExpenses(moneyRequestReport?.reportID);
   142      const displayedAmount = isAnyTransactionOnHold && canAllowSettlement ? nonHeldAmount : formattedAmount;
   143      const isMoreContentShown = shouldShowNextStep || shouldShowStatusBar || (shouldShowAnyButton && shouldUseNarrowLayout);
   144      const {isDelegateAccessRestricted, delegatorEmail} = useDelegateUserDetails();
   145      const [isNoDelegateAccessMenuVisible, setIsNoDelegateAccessMenuVisible] = useState(false);
   146
   147      const confirmPayment = useCallback(
   148          (type?: PaymentMethodType | undefined, payAsBusiness?: boolean) => {
   149              if (!type || !chatReport) {
   150                  return;
   151              }
   152              setPaymentType(type);
   153              setRequestType(CONST.IOU.REPORT_ACTION_TYPE.PAY);
   154              if (isDelegateAccessRestricted) {
   155                  setIsNoDelegateAccessMenuVisible(true);
   156              } else if (isAnyTransactionOnHold) {
   157                  setIsHoldMenuVisible(true);
   158              } else if (ReportUtils.isInvoiceReport(moneyRequestReport)) {
   159                  IOU.payInvoice(type, chatReport, moneyRequestReport, payAsBusiness);
   160              } else {
   161                  IOU.payMoneyRequest(type, chatReport, moneyRequestReport, true);
   162              }
   163          },
   164          [chatReport, isAnyTransactionOnHold, isDelegateAccessRestricted, moneyRequestReport],
   165      );
   166
   167      const confirmApproval = () => {
   168          setRequestType(CONST.IOU.REPORT_ACTION_TYPE.APPROVE);
   169          if (isDelegateAccessRestricted) {
   170              setIsNoDelegateAccessMenuVisible(true);
   171          } else if (isAnyTransactionOnHold) {
   172              setIsHoldMenuVisible(true);
   173          } else {
   174              IOU.approveMoneyRequest(moneyRequestReport, true);
   175          }
   176      };
   177
   178      const deleteTransaction = useCallback(() => {
   179          if (requestParentReportAction) {
   180              const iouTransactionID = ReportActionsUtils.isMoneyRequestAction(requestParentReportAction)
   181                  ? ReportActionsUtils.getOriginalMessage(requestParentReportAction)?.IOUTransactionID ?? '-1'
   182                  : '-1';
   183              if (ReportActionsUtils.isTrackExpenseAction(requestParentReportAction)) {
   184                  navigateBackToAfterDelete.current = IOU.deleteTrackExpense(moneyRequestReport?.reportID ?? '-1', iouTransactionID, requestParentReportAction, true);
   185              } else {
   186                  navigateBackToAfterDelete.current = IOU.deleteMoneyRequest(iouTransactionID, requestParentReportAction, true);
   187              }
   188          }
   189
   190          setIsDeleteRequestModalVisible(false);
   191      }, [moneyRequestReport?.reportID, requestParentReportAction, setIsDeleteRequestModalVisible]);
   192
   193      const markAsCash = useCallback(() => {
   194          if (!requestParentReportAction) {
   195              return;
   196          }
   197          const iouTransactionID = ReportActionsUtils.isMoneyRequestAction(requestParentReportAction)
   198              ? ReportActionsUtils.getOriginalMessage(requestParentReportAction)?.IOUTransactionID ?? '-1'
   199              : '-1';
   200          const reportID = transactionThreadReport?.reportID ?? '-1';
   201
   202          TransactionActions.markAsCash(iouTransactionID, reportID);
   203      }, [requestParentReportAction, transactionThreadReport?.reportID]);
   204
   205      const getStatusIcon: (src: IconAsset) => React.ReactNode = (src) => (
   206          <Icon
   207              src={src}
   208              height={variables.iconSizeSmall}
   209              width={variables.iconSizeSmall}
   210              fill={theme.icon}
   211          />
   212      );
   213
   214      const getStatusBarProps: () => MoneyRequestHeaderStatusBarProps | undefined = () => {
   215          if (isPayAtEndExpense) {
   216              if (!isArchivedReport) {
   217                  return {icon: getStatusIcon(Expensicons.Hourglass), description: translate('iou.bookingPendingDescription')};
   218              }
   219              if (isArchivedReport && archiveReason === CONST.REPORT.ARCHIVE_REASON.BOOKING_END_DATE_HAS_PASSED) {
   220                  return {icon: getStatusIcon(Expensicons.Box), description: translate('iou.bookingArchivedDescription')};
   221              }
   222          }
   223          if (hasOnlyHeldExpenses) {
   224              return {icon: getStatusIcon(Expensicons.Stopwatch), description: translate('iou.expensesOnHold')};
   225          }
   226          if (hasAllPendingRTERViolations) {
   227              return {icon: getStatusIcon(Expensicons.Hourglass), description: translate('iou.pendingMatchWithCreditCardDescription')};
   228          }
   229          if (hasOnlyPendingTransactions) {
   230              return {icon: getStatusIcon(Expensicons.CreditCardHourglass), description: translate('iou.transactionPendingDescription')};
   231          }
   232          if (hasScanningReceipt) {
   233              return {icon: getStatusIcon(Expensicons.ReceiptScan), description: translate('iou.receiptScanInProgressDescription')};
   234          }
   235      };
   236
   237      const statusBarProps = getStatusBarProps();
   238
   239      // The submit button should be success green colour only if the user is submitter and the policy does not have Scheduled Submit turned on
   240      const isWaitingForSubmissionFromCurrentUser = useMemo(
   241          () => chatReport?.isOwnPolicyExpenseChat && !policy?.harvesting?.enabled,
   242          [chatReport?.isOwnPolicyExpenseChat, policy?.harvesting?.enabled],
   243      );
   244
   245      useEffect(() => {
   246          if (isLoadingHoldUseExplained) {
   247              return;
   248          }
   249          setShouldShowHoldMenu(isOnHold && !dismissedHoldUseExplanation);
   250      }, [dismissedHoldUseExplanation, isLoadingHoldUseExplained, isOnHold]);
   251
   252      useEffect(() => {
   253          if (!shouldShowHoldMenu) {
   254              return;
   255          }
   256
   257          if (isSmallScreenWidth) {
   258              if (Navigation.getActiveRoute().slice(1) === ROUTES.PROCESS_MONEY_REQUEST_HOLD.route) {
   259                  Navigation.goBack();
   260              }
   261          } else {
   262              Navigation.navigate(ROUTES.PROCESS_MONEY_REQUEST_HOLD.getRoute(Navigation.getReportRHPActiveRoute()));
   263          }
   264      }, [isSmallScreenWidth, shouldShowHoldMenu]);
   265
   266      const handleHoldRequestClose = () => {
   267          IOU.dismissHoldUseExplanation();
   268      };
   269
   270      useEffect(() => {
   271          if (canDeleteRequest) {
   272              return;
   273          }
   274
   275          setIsDeleteRequestModalVisible(false);
   276      }, [canDeleteRequest]);
   277
   278      return (
   279          <View style={[styles.pt0]}>
   280              <HeaderWithBackButton
   281                  shouldShowReportAvatarWithDisplay
   282                  shouldEnableDetailPageNavigation
   283                  shouldShowPinButton={false}
   284                  report={moneyRequestReport}
   285                  policy={policy}
   286                  shouldShowBackButton={shouldUseNarrowLayout}
   287                  shouldDisplaySearchRouter
   288                  onBackButtonPress={onBackButtonPress}
   289                  // Shows border if no buttons or banners are showing below the header
   290                  shouldShowBorderBottom={!isMoreContentShown}
   291              >
   292                  {shouldShowSettlementButton && !shouldUseNarrowLayout && (
   293                      <View style={styles.pv2}>
   294                          <SettlementButton
   295                              currency={moneyRequestReport?.currency}
   296                              confirmApproval={confirmApproval}
   297                              policyID={moneyRequestReport?.policyID}
   298                              chatReportID={chatReport?.reportID}
   299                              iouReport={moneyRequestReport}
   300                              onPress={confirmPayment}
   301                              enablePaymentsRoute={ROUTES.ENABLE_PAYMENTS}
   302                              addBankAccountRoute={bankAccountRoute}
   303                              shouldHidePaymentOptions={!shouldShowPayButton}
   304                              shouldShowApproveButton={shouldShowApproveButton}
   305                              shouldDisableApproveButton={shouldDisableApproveButton}
   306                              style={[styles.pv2]}
   307                              formattedAmount={!hasOnlyHeldExpenses ? displayedAmount : ''}
   308                              isDisabled={isOffline && !canAllowSettlement}
   309                              isLoading={!isOffline && !canAllowSettlement}
   310                          />
   311                      </View>
   312                  )}
   313                  {shouldShowExportIntegrationButton && !shouldUseNarrowLayout && (
   314                      <View style={[styles.pv2]}>
   315                          <ExportWithDropdownMenu
   316                              policy={policy}
   317                              report={moneyRequestReport}
   318                              connectionName={connectedIntegration}
   319                          />
   320                      </View>
   321                  )}
   322                  {shouldShowSubmitButton && !shouldUseNarrowLayout && (
   323                      <View style={styles.pv2}>
   324                          <Button
   325                              success={isWaitingForSubmissionFromCurrentUser}
   326                              text={translate('common.submit')}
   327                              style={[styles.mnw120, styles.pv2, styles.pr0]}
   328                              onPress={() => IOU.submitReport(moneyRequestReport)}
   329                              isDisabled={shouldDisableSubmitButton}
   330                          />
   331                      </View>
   332                  )}
   333                  {hasAllPendingRTERViolations && !shouldUseNarrowLayout && (
   334                      <View style={[styles.pv2]}>
   335                          <Button
   336                              success
   337                              text={translate('iou.markAsCash')}
   338                              style={[styles.pv2, styles.pr0]}
   339                              onPress={markAsCash}
   340                          />
   341                      </View>
   342                  )}
   343              </HeaderWithBackButton>
   344              {isMoreContentShown && (
   345                  <View style={[styles.dFlex, styles.flexColumn, styles.gap3, styles.pb3, styles.ph5, styles.borderBottom]}>
   346                      {shouldShowSettlementButton && shouldUseNarrowLayout && (
   347                          <SettlementButton
   348                              currency={moneyRequestReport?.currency}
   349                              confirmApproval={confirmApproval}
   350                              policyID={moneyRequestReport?.policyID}
   351                              chatReportID={moneyRequestReport?.chatReportID}
   352                              iouReport={moneyRequestReport}
   353                              onPress={confirmPayment}
   354                              enablePaymentsRoute={ROUTES.ENABLE_PAYMENTS}
   355                              addBankAccountRoute={bankAccountRoute}
   356                              shouldHidePaymentOptions={!shouldShowPayButton}
   357                              shouldShowApproveButton={shouldShowApproveButton}
   358                              formattedAmount={!hasOnlyHeldExpenses ? displayedAmount : ''}
   359                              shouldDisableApproveButton={shouldDisableApproveButton}
   360                              isDisabled={isOffline && !canAllowSettlement}
   361                              isLoading={!isOffline && !canAllowSettlement}
   362                          />
   363                      )}
   364                      {shouldShowExportIntegrationButton && shouldUseNarrowLayout && (
   365                          <ExportWithDropdownMenu
   366                              policy={policy}
   367                              report={moneyRequestReport}
   368                              connectionName={connectedIntegration}
   369                          />
   370                      )}
   371                      {shouldShowSubmitButton && shouldUseNarrowLayout && (
   372                          <Button
   373                              success={isWaitingForSubmissionFromCurrentUser}
   374                              text={translate('common.submit')}
   375                              style={[styles.w100, styles.pr0]}
   376                              onPress={() => IOU.submitReport(moneyRequestReport)}
   377                              isDisabled={shouldDisableSubmitButton}
   378                          />
   379                      )}
   380                      {hasAllPendingRTERViolations && shouldUseNarrowLayout && (
   381                          <Button
   382                              success
   383                              text={translate('iou.markAsCash')}
   384                              style={[styles.w100, styles.pr0]}
   385                              onPress={markAsCash}
   386                          />
   387                      )}
   388                      {shouldShowNextStep && <MoneyReportHeaderStatusBar nextStep={nextStep} />}
   389                      {statusBarProps && (
   390                          <MoneyRequestHeaderStatusBar
   391                              icon={statusBarProps.icon}
   392                              description={statusBarProps.description}
   393                          />
   394                      )}
   395                  </View>
   396              )}
   397              {isHoldMenuVisible && requestType !== undefined && (
   398                  <ProcessMoneyReportHoldMenu
   399                      nonHeldAmount={!hasOnlyHeldExpenses ? nonHeldAmount : undefined}
   400                      requestType={requestType}
   401                      fullAmount={fullAmount}
   402                      onClose={() => setIsHoldMenuVisible(false)}
   403                      isVisible={isHoldMenuVisible}
   404                      paymentType={paymentType}
   405                      chatReport={chatReport}
   406                      moneyRequestReport={moneyRequestReport}
   407                      transactionCount={transactionIDs.length}
   408                  />
   409              )}
   410              <DelegateNoAccessModal
   411                  isNoDelegateAccessMenuVisible={isNoDelegateAccessMenuVisible}
   412                  onClose={() => setIsNoDelegateAccessMenuVisible(false)}
   413                  delegatorEmail={delegatorEmail ?? ''}
   414              />
   415
   416              <ConfirmModal
   417                  title={translate('iou.deleteExpense', {count: 1})}
   418                  isVisible={isDeleteRequestModalVisible}
   419                  onConfirm={deleteTransaction}
   420                  onCancel={() => setIsDeleteRequestModalVisible(false)}
   421                  onModalHide={() => ReportUtils.navigateBackAfterDeleteTransaction(navigateBackToAfterDelete.current)}
   422                  prompt={translate('iou.deleteConfirmation', {count: 1})}
   423                  confirmText={translate('common.delete')}
   424                  cancelText={translate('common.cancel')}
   425                  danger
   426                  shouldEnableNewFocusManagement
   427              />
   428              {isSmallScreenWidth && shouldShowHoldMenu && (
   429                  <ProcessMoneyRequestHoldMenu
   430                      onClose={handleHoldRequestClose}
   431                      onConfirm={handleHoldRequestClose}
   432                      isVisible={shouldShowHoldMenu}
   433                  />
   434              )}
   435          </View>
   436      );
   437  }
   438
   439  MoneyReportHeader.displayName = 'MoneyReportHeader';
   440
   441  export default MoneyReportHeader;

