1  import React, {useCallback, useEffect, useRef} from 'react';
     2  import {View} from 'react-native';
     3  import type {OnyxEntry} from 'react-native-onyx';
     4  import {useOnyx, withOnyx} from 'react-native-onyx';
     5  import type {ValueOf} from 'type-fest';
     6  import useStyleUtils from '@hooks/useStyleUtils';
     7  import useTheme from '@hooks/useTheme';
     8  import useThemeStyles from '@hooks/useThemeStyles';
     9  import Navigation from '@libs/Navigation/Navigation';
    10  import * as OptionsListUtils from '@libs/OptionsListUtils';
    11  import * as ReportUtils from '@libs/ReportUtils';
    12  import CONST from '@src/CONST';
    13  import ONYXKEYS from '@src/ONYXKEYS';
    14  import ROUTES from '@src/ROUTES';
    15  import type {PersonalDetailsList, Policy, Report, ReportActions} from '@src/types/onyx';
    16  import CaretWrapper from './CaretWrapper';
    17  import DisplayNames from './DisplayNames';
    18  import MultipleAvatars from './MultipleAvatars';
    19  import ParentNavigationSubtitle from './ParentNavigationSubtitle';
    20  import PressableWithoutFeedback from './Pressable/PressableWithoutFeedback';
    21  import SubscriptAvatar from './SubscriptAvatar';
    22  import Text from './Text';
    23
    24  type AvatarWithDisplayNamePropsWithOnyx = {
    25      /** All of the actions of the report */
    26      parentReportActions: OnyxEntry<ReportActions>;
    27
    28      /** Personal details of all users */
    29      personalDetails: OnyxEntry<PersonalDetailsList>;
    30  };
    31
    32  type AvatarWithDisplayNameProps = AvatarWithDisplayNamePropsWithOnyx & {
    33      /** The report currently being looked at */
    34      report: OnyxEntry<Report>;
    35
    36      /** The policy which the user has access to and which the report is tied to */
    37      policy?: OnyxEntry<Policy>;
    38
    39      /** The size of the avatar */
    40      size?: ValueOf<typeof CONST.AVATAR_SIZE>;
    41
    42      /** Whether if it's an unauthenticated user */
    43      isAnonymous?: boolean;
